from dataclasses import dataclass
from enum import Enum

from pydantic import BaseModel
from uipath.platform import UiPath
from uipath.tracing import traced


class ReviewDecision(str, Enum):
    approved = "approved"
    requested_changes = "requested_changes"
    recused = "recused"


class Reviewer(BaseModel):
    name: str
    decision: ReviewDecision


class ReviewOutcome(BaseModel):
    reviewers: list[Reviewer]


@dataclass
class ApproverCountIn:
    sentence: str


@dataclass
class ApproverCountOut:
    approver_count: int


SYSTEM_PROMPT = """You analyze a single sentence describing the outcome of a proposal \
review round. Identify every person mentioned by name and, for each one, decide whether \
they approved the proposal, requested changes to it, or recused themselves from the \
review. Classify every mentioned person into exactly one of these three categories \
based only on what the sentence states."""


@traced()
async def main(input: ApproverCountIn) -> ApproverCountOut:
    sdk = UiPath()

    response = await sdk.llm.chat_completions(
        messages=[
            {"role": "system", "content": SYSTEM_PROMPT},
            {"role": "user", "content": input.sentence},
        ],
        response_format=ReviewOutcome,
    )

    outcome = ReviewOutcome.model_validate_json(response.choices[0].message.content)
    approver_count = sum(
        1 for reviewer in outcome.reviewers if reviewer.decision == ReviewDecision.approved
    )

    return ApproverCountOut(approver_count=approver_count)

